create table public.financial_audit_logs(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,user_id uuid references public.app_users(id) on delete set null,audit_number text not null,audit_type text not null default 'monthly' check(audit_type in ('daily','weekly','monthly','quarterly','yearly','custom')),start_date date not null,end_date date not null,status text not null default 'pending' check(status in ('pending','in_progress','completed','cancelled')),opening_balance numeric not null default 0,total_revenue numeric not null default 0,total_expenses numeric not null default 0,closing_balance numeric not null default 0,variance numeric not null default 0,notes text,metadata jsonb,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,audit_number));
create table public.auto_order_rules(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,product_id bigint not null references public.products(id) on delete cascade,enabled boolean not null default true,min_stock_level numeric(12,2),max_stock_level numeric(12,2),reorder_point numeric(12,2),safety_stock numeric(12,2),lead_time_days integer,min_order_qty numeric(12,2),max_order_qty numeric(12,2),order_multiple numeric(12,2),preferred_supplier_id bigint references public.parties(id) on delete set null,auto_approve boolean not null default false,meta jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,product_id));
create table public.auto_order_suggestions(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,product_id bigint not null references public.products(id) on delete cascade,preferred_supplier_id bigint references public.parties(id) on delete set null,predicted_demand numeric(12,2) not null default 0,current_stock numeric(12,2) not null default 0,pending_purchases numeric(12,2) not null default 0,suggested_order_qty numeric(12,2) not null default 0,confidence_score numeric(5,2),priority text not null default 'medium',status text not null default 'pending',approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,converted_purchase_id bigint references public.purchases(id) on delete set null,converted_at timestamptz,notes text,reasoning jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['financial_audit_logs','auto_order_rules','auto_order_suggestions'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon,authenticated',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); end loop; end $$;
create policy financial_audit_logs_tenant on public.financial_audit_logs for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy auto_order_rules_tenant on public.auto_order_rules for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy auto_order_suggestions_tenant on public.auto_order_suggestions for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));